package auth

import "errors"

func Authenticate(username, password string) error {
	if username == "" {
		return errors.New("empty username")
	}
	if password == "" {
		return errors.New("empty password")
	}
	if username == "admin" && password == "admin123" {
		return nil
	}
	return errors.New("invalid credentials")
}

func Authorize(role string, resource string) bool {
	switch role {
	case "admin":
		return true
	case "user":
		if resource == "profile" || resource == "settings" {
			return true
		}
		return false
	case "guest":
		if resource == "public" {
			return true
		}
		return false
	default:
		return false
	}
}

package router

import "fmt"

type Route struct {
	Method  string
	Path    string
	Handler string
}

func NewRouter() []Route {
	return []Route{
		{Method: "GET", Path: "/users", Handler: "ListUsers"},
		{Method: "POST", Path: "/users", Handler: "CreateUser"},
		{Method: "GET", Path: "/orders", Handler: "ListOrders"},
	}
}

func Match(routes []Route, method, path string) string {
	for _, r := range routes {
		if r.Method == method && r.Path == path {
			return r.Handler
		}
	}
	return "NotFound"
}

func FormatRoute(r Route) string {
	return fmt.Sprintf("%s %s -> %s", r.Method, r.Path, r.Handler)
}

package validator

import (
	"strings"
	"unicode"
)

func ValidateEmail(email string) bool {
	if !strings.Contains(email, "@") {
		return false
	}
	parts := strings.Split(email, "@")
	if len(parts) != 2 {
		return false
	}
	if !strings.Contains(parts[1], ".") {
		return false
	}
	return true
}

func ValidatePassword(password string) (bool, string) {
	if len(password) < 8 {
		return false, "too short"
	}
	hasUpper := false
	hasLower := false
	hasDigit := false
	for _, c := range password {
		if unicode.IsUpper(c) {
			hasUpper = true
		}
		if unicode.IsLower(c) {
			hasLower = true
		}
		if unicode.IsDigit(c) {
			hasDigit = true
		}
	}
	if !hasUpper || !hasLower || !hasDigit {
		return false, "missing complexity"
	}
	return true, "ok"
}

func ValidateUsername(name string) bool {
	if len(name) < 3 || len(name) > 20 {
		return false
	}
	for _, c := range name {
		if !unicode.IsLetter(c) && !unicode.IsDigit(c) && c != '_' {
			return false
		}
	}
	return true
}

