{
  "name": "CI Pipeline",
  "on": {
    "push": {"branches": ["main", "develop"]},
    "pull_request": {"branches": ["main"]}
  },
  "env": {"GO_VERSION": "1.22", "NODE_VERSION": "20"},
  "jobs": [
    {
      "id": "lint",
      "runs_on": "ubuntu-latest",
      "steps": [
        {"uses": "actions/checkout@v4"},
        {"uses": "actions/setup-go@v5", "with": {"go-version": "${{GO_VERSION}}"}},
        {"run": "golangci-lint run"}
      ]
    },
    {
      "id": "test",
      "runs_on": "ubuntu-latest",
      "steps": [
        {"uses": "actions/checkout@v4"},
        {"uses": "actions/setup-go@v5", "with": {"go-version": "${{GO_VERSION}}"}},
        {"run": "go test -race -coverprofile=coverage.out ./..."},
        {"uses": "actions/upload-artifact@v4", "with": {"name": "coverage", "path": "coverage.out"}}
      ]
    },
    {
      "id": "build",
      "runs_on": "ubuntu-latest",
      "needs": ["lint", "test"],
      "steps": [
        {"uses": "actions/checkout@v4"},
        {"run": "go build -o bin/app ./cmd/app"},
        {"uses": "actions/upload-artifact@v4", "with": {"name": "binary", "path": "bin/app"}}
      ]
    },
    {
      "id": "deploy",
      "runs_on": "ubuntu-latest",
      "needs": ["build"],
      "if": "github.ref == 'refs/heads/main'",
      "steps": [
        {"uses": "actions/checkout@v4"},
        {"run": "echo 'Deploying to production...'"}
      ]
    }
  ]
}

